xml.Script:
        Colors[ 0] := '0000FF'; // Blue
        Colors[ 1] := 'FF0000'; // Red
        Colors[ 2] := '008000'; // Green
        Colors[ 3] := 'FFFF00'; // Yellow
        Colors[ 4] := '800080'; // Purple
        Colors[ 5] := '00FFFF'; // Cyan
        Colors[ 6] := 'FF7F50'; // Coral
        Colors[ 7] := '00FF00'; // Lime
        Colors[ 8] := 'DDBB20'; // Golden
        Colors[ 9] := 'FF69B4'; // Pink
        Colors[10] := 'FF6000'; // Orange
        Colors[11] := 'F0E68C'; // Khaki
        Colors[12] := 'ADFF2F'; // GreenYellow
        Colors[13] := '006400'; // DarkGreen
        Colors[14] := '00BFFF'; // DeepSky
        Colors[15] := '000080'; // Navy
        Colors[16] := 'DC143C'; // Crimson
        Colors[17] := 'CD5C5C'; // Indian
        Colors[18] := 'FF00FF'; // Fuchsia
        Colors[19] := 'D07090'; // Pale

        R := 0.7;
        H := R * 0.5;  // arbitrary

        R1 := 1 / (sin(Pi/5) / H + 1 / R * cos(Pi/5));
        H1 := H * (1 - R1 / R / cos(Pi/5));
        D1 := R1 * cos(Pi / 5);
        D2 := R1 * cos(2 * Pi / 5);

        sAngle := Pi * 2 / 5;
        for i := 0 to 4 do begin
            x[i] := R * sin(sAngle * i);
            y[i] := R * cos(sAngle * i);
            xi[i] := R1 * sin(sAngle * (i + 0.5));
            yi[i] := R1 * cos(sAngle * (i + 0.5));
        end;
